	/**
	 * Default Constructor
	 */
    public StockAdjustmentService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new StockAdjustmentEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(StockAdjustmentRepository.class) );
		this.validator		= applicationContext.getBean(StockAdjustmentValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		StockAdjustment
	 */
		public StockAdjustment createStockAdjustment( CreateStockAdjustmentCommand command ) {

		StockAdjustment entity = new StockAdjustment();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setStockAdjustmentId( command.getStockAdjustmentId() );
            entity.setAdjustmentNumber( command.getAdjustmentNumber() );
            entity.setReason( command.getReason() );
            entity.setAdjustmentDate( command.getAdjustmentDate() );
            entity.setAdjustmentType( command.getAdjustmentType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of StockAdjustment {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateStockAdjustmentCommand
	 * @return		StockAdjustment
	 */
	public StockAdjustment updateStockAdjustment( UpdateStockAdjustmentCommand command ) {

		StockAdjustment entity = new StockAdjustment();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setStockAdjustmentId( command.getStockAdjustmentId() );
            entity.setAdjustmentNumber( command.getAdjustmentNumber() );
            entity.setReason( command.getReason() );
            entity.setAdjustmentDate( command.getAdjustmentDate() );
            entity.setWarehouse( command.getWarehouse() );
            entity.setLines( command.getLines() );
            entity.setTransactions( command.getTransactions() );
            entity.setAdjustmentType( command.getAdjustmentType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of StockAdjustment {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteStockAdjustmentCommand
	 */
	public void delete( DeleteStockAdjustmentCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getStockAdjustmentId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of StockAdjustment {0} ", id );

	}

	/**
	 * Method to retrieve the StockAdjustment via StockAdjustmentFetchOneSummary
	 * @param 	summary StockAdjustmentFetchOneSummary
	 * @return 	StockAdjustmentFetchOneResponse
	 */
	public StockAdjustment getStockAdjustment( StockAdjustmentFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "StockAdjustmentFetchOneSummary arg cannot be null" );

		StockAdjustment entity = null;
		UUID id = summary.getStockAdjustmentId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a StockAdjustment using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all StockAdjustments
	 *
	 * @return 	List<StockAdjustment>
	 */
    public List<StockAdjustment> getAllStockAdjustment() {
		List<StockAdjustment> list = projector.findAll( new FindAllStockAdjustmentQuery() );
		return list;
	}

	/**
	 * assign Warehouse on StockAdjustment
	 * @param		command AssignWarehouseToStockAdjustmentCommand
	 */
	public void assignWarehouse( AssignWarehouseToStockAdjustmentCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignWarehouse(command.getStockAdjustmentId(), command.getAssignment());

	}

